20	    // true si la pregunta menciona (por id o nombre) a algún estudiante que el usuario no puede ver.
21	    public static bool MencionaTercero(Datos datos, Usuario usuario, string pregunta)
22	    {
23	        var tokens = Tokenizar(pregunta);
24	        var conjunto = new HashSet<string>(tokens);
25	        foreach (var e in datos.Estudiantes)
26	        {
27	            if (usuario.Rol == "estudiante" && e.Id == usuario.Id) continue;
28	            if (PuedeVerEstudiante(datos, usuario, e.Id)) continue;
29	            if (ContieneId(tokens, string.Concat(Tokenizar(e.Id)))) return true;
30	            var partes = Tokenizar(e.Nombre);
31	            if (partes.Count > 0 && conjunto.Contains(partes[0])) return true;
32	        }
33	        return false;
34	    }
