36	    // El id colapsado (solo letras y dígitos) coincide con un token o con tokens consecutivos concatenados.
37	    static bool ContieneId(List<string> tokens, string clave)
38	    {
39	        if (clave.Length == 0) return false;
40	        for (var i = 0; i < tokens.Count; i++)
41	        {
42	            var acc = "";
43	            for (var j = i; j < tokens.Count; j++)
44	            {
45	                acc += tokens[j];
46	                if (acc == clave) return true;
47	                if (!clave.StartsWith(acc, StringComparison.Ordinal)) break;
48	            }
49	        }
50	        return false;
51	    }
52	
53	    // FormKD, sin categorías Cf/Mn, minúsculas; luego secuencias de letras/dígitos.
54	    static List<string> Tokenizar(string? s)
55	    {
56	        var sb = new StringBuilder();
57	        foreach (var c in (s ?? "").Normalize(NormalizationForm.FormKD))
58	        {
59	            var cat = CharUnicodeInfo.GetUnicodeCategory(c);
60	            if (cat == UnicodeCategory.Format || cat == UnicodeCategory.NonSpacingMark) continue;
61	            sb.Append(char.IsLetterOrDigit(c) ? char.ToLowerInvariant(c) : ' ');
62	        }
63	        return sb.ToString().Split(' ', StringSplitOptions.RemoveEmptyEntries).ToList();
64	    }
